def _without_apple_comparison_context(text: str) -> str:
    # A platform used only as the object of a comparison is not the subject
    # of this source's software action. Keep the rest of the same sentence,
    # including any independently stated current Apple action.
    return _compiled_rule(r"(?:和|与|跟)\s*(?:苹果|apple|iphone|ipad|siri|ios|macos)[^。！？;；]{0,120}?(?:类似|相似|一样)|"
        r"\b(?:similar\s+to|as\s+with|unlike|just\s+like)\s+(?:apple(?:['’]s)?|iphone|ipad|siri|ios|macos)\b[^,;.!?]{0,120}", re.I).sub(" ", text, 0)


def is_apple_os_feature_or_summary_story(text: str) -> bool:
    text = _without_apple_comparison_context(text)
    lower = text.lower()
    if effective_apple_term_score(lower) <= 0:
        return False
    if (
        is_messages_platform_candidate(text)
        or is_macos_terminal_paste_security_story(text)
        or is_third_party_platform_availability_candidate(text)
        or is_routine_third_party_apple_platform_story(text)
    ):
        return False
    if score_terms(lower, APPLE_OS_PLATFORM_TERMS) <= 0:
        return False
    if score_terms(
        lower,
        [
            "top stories",
            "weekly recap",
            "daily:",
            "9to5mac daily",
            "hands-on",
            "alternative",
            "third-party",
            "recap links",
            "本周回顾",
            "一周回顾",
            "动手体验",
            "替代品",
            "第三方",
        ],
    ) > 0:
        return False
    summary_score = score_terms(lower, OS_SUMMARY_TERMS)
    component_score = score_terms(lower, APPLE_OS_COMPONENT_TERMS)
    action_score = score_terms(
        lower,
        OS_FEATURE_ACTION_TERMS
        + POSITIVE_ACTION_TERMS
        + [
            "new",
            "new in",
            "enhancement",
            "enhancements",
            "improvement",
            "improvements",
            "brings",
            "bring",
            "write with siri",
            "retire",
            "retires",
            "retirement",
            "going away",
            "sunset",
            "remove from app store",
            "更新点",
            "新变化",
            "增强",
            "退场",
            "下架",
        ],
    )
    if summary_score > 0 and score_terms(lower, ["beta", "developer beta", "更新", "新增"]) > 0:
        return True
    return component_score > 0 and action_score > 0


