def score_messages_platform_terms(text: str) -> int:
    lower = text.lower()
    score = 0
    for term in MESSAGE_PLATFORM_TERMS:
        if not term_present(lower, term.lower()):
            continue
        pattern = re.compile(
            r"(?:\b(?:no|not|without|never)\b|没有|未|尚未|无|并未|不(?:会|能|是)?)"
            r"[^。.!?]{0,32}"
            r"(?:integrat\w*|available|support\w*|use|接入|支持|可用)?"
            r"[^。.!?]{0,32}"
            + re.escape(term.lower()),
            re.I,
        )
        if pattern.search(lower):
            continue
        score += 1
    return score


def score_messages_platform_actions(text: str) -> int:
    lower = text.lower()
    score = 0
    for term in MESSAGE_PLATFORM_ACTION_TERMS:
        if not term_present(lower, term.lower()):
            continue
        pattern = re.compile(
            r"(?:\b(?:no|not|without|never)\b|没有|未|尚未|无|并未|不(?:会|能|是)?)"
            r"[^。.!?]{0,32}"
            + re.escape(term.lower()),
            re.I,
        )
        if pattern.search(lower):
            continue
        score += 1
    return score


def is_relevant_candidate(
    candidate: Candidate,
    source: Source,
    key_facts: list[str] | None = None,
) -> bool:
    if collection.is_navigation_url(candidate.url, source):
        return False
    if is_source_daily_brief_candidate(candidate, source):
        return False
    if key_facts is not None:
        # Detail eligibility belongs to the source identity authority. The
        # discovery headline gate cannot veto a verified later Apple result.
        if source_market_measurement_frame(candidate.title, candidate.summary, tuple(key_facts)):
            return True
    url_lower = candidate.url.lower()
    text = f"{candidate.title} {candidate.summary} {candidate.context}"
    lower_text = text.lower()
    apple_score = effective_apple_term_score(text)
    if apple_score <= 0:
        apple_score = score_terms(text, DISCOVERY_PRODUCT_TERMS)
    if apple_score <= 0:
        if key_facts is None and collection.market_summary_needs_detail(candidate.title):
            return True
        if source.name != "Apple Newsroom":
            return False
        action_score = score_terms(text, POSITIVE_ACTION_TERMS)
        if action_score <= 0:
            return False
        apple_score = 1
    else:
        action_score = score_terms(text, POSITIVE_ACTION_TERMS)
    if is_non_apple_primary_legal_story_with_incidental_apple_context(
        candidate.title,
        candidate.summary,
        candidate.context,
    ):
        return False
    semantic_identity = title_led_identity(candidate.title, candidate.summary)
    direct_report = collection.direct_apple_report_needs_detail(
        semantic_identity, has_lead=bool(candidate.summary.strip())) or is_institutional_apple_device_purchase(candidate.title, candidate.summary)
    # Product names can collide with a lexical URL hint. Structural guide,
    # review, deal and navigation exclusions still use their existing gates.
    product_url_collision = (direct_report and "podcast" in url_lower
        and not url_has_excluded_fragment(url_lower.replace("podcast", "")))
    if url_has_excluded_fragment(candidate.url) and not product_url_collision:
        if not allowed_url_excluded_candidate(candidate, source, text):
            return False
    direct_title_event = (
        is_apple_device_battery_regulation_story(text)
        or is_apple_product_applied_research_story(candidate.title, text)
        or is_apple_product_driven_market_forecast_story(candidate.title, text)
        or is_concrete_apple_event_operations_story(candidate.title, text)
        or is_direct_apple_product_adoption_story(candidate.title, text)
        or is_apple_chip_tariff_exemption_story(candidate.title, text)
        or is_direct_apple_regulated_technology_access_story(candidate.title, text)
        or is_direct_apple_os_component_change_story(candidate.title, text)
        or is_apple_specific_market_share_report_story(text, candidate.title)
        or has_direct_apple_subject_context(candidate.title)
        or is_apple_strategic_transaction_story(candidate.title)
        or is_material_apple_stock_move_story(candidate.title, text)
        or is_direct_apple_first_party_developer_guidance_story(candidate.title, text)
        or is_apple_led_developer_submission_story(candidate.title, candidate.summary)
        or is_official_apple_education_promotion_story(candidate.title, text)
        or is_applecare_plan_price_change_story(candidate.title, text)
        or is_first_party_applecare_plan_change_story(candidate.title, text)
        or is_direct_apple_restricted_mode_clarification_story(candidate.title, text)
        or is_ipad_carrier_financing_story(candidate.title, text)
        or is_apple_intelligence_china_regulatory_rollout_story(candidate.title, text)
        or is_apple_ai_chip_acquisition_story(candidate.title, text)
        or is_apple_maps_ad_policy_story(candidate.title, text)
        or is_brazil_minor_gambling_app_inquiry_story(candidate.title, text)
        or is_apple_sales_tax_holiday_story(candidate.title, text)
        or is_direct_apple_platform_malware_report_story(candidate.title, text)
        or is_direct_apple_regulatory_trade_action_story(candidate.title, text)
        or is_apple_display_supplier_price_negotiation_story(candidate.title, text)
        or is_direct_apple_facility_incident_story(candidate.title, text)
        or is_direct_apple_platform_security_impact_story(candidate.title, text)
    )
    if should_hard_exclude_candidate(text) and not (direct_title_event or direct_report):
        return False
    strong_score = score_terms(text, STRONG_NEWS_ACTION_TERMS)
    exclude_score = score_terms(text, EXCLUDE_TERMS)
    if is_routine_retail_discount_story(candidate.title, text):
        return False
    if high_confidence_direct_apple_action(semantic_identity):
        return True
    has_report_evidence = bool(
        semantic_identity.actions
        or ((candidate.summary.strip() or key_facts) and exclude_score == 0)
    )
    if semantic_identity.scope == "apple-direct" and (
        has_report_evidence or semantic_identity.content_form != "news"
    ):
        # Admission preserves a directly reported Apple subject for detail
        # verification. Relevance is decided downstream; legacy action words
        # must not veto it or make a cleaned article depend on feed boilerplate.
        return True
    if collection.current_apple_role_interview_needs_detail(candidate.title, candidate.summary, semantic_identity):
        return True
    classification_facts = [candidate.context, *(key_facts or [])]
    candidate_event_kind = detect_event_kind(candidate.title, candidate.summary, classification_facts)
    if collection.sparse_apple_subject_needs_detail(
        semantic_identity, has_lead=bool(candidate.summary.strip()), event_kind=candidate_event_kind, title=candidate.title
    ):
        return True
    profile = source_text_profile(candidate.title, candidate.summary, classification_facts, candidate.source)
    if profile.eligibility is not None and not profile.eligibility.resolved:
        return True  # Discovery needs the detail evidence to resolve this source.
    candidate_tier, _, _ = resolve_reconciliation_outcome(
        profile, observed_tier="", observed_reason="", observed_category="")
    if (
        candidate_tier == "weak"
        and is_third_party_consumer_app_update_on_apple_platform(candidate.title, text)
    ):
        # Preserve explicit Apple-platform third-party updates for deferred
        # review instead of narrowing discovery when their final tier is weak.
        return True
    if (
        candidate_tier == "weak"
        and semantic_identity.scope == "third-party-context"
        and semantic_identity.title_products
    ):
        # A title-led Apple comparison or compatibility story remains useful
        # evidence for deferred review. Admit it to detail parsing, but leave
        # the structured relevance tier authoritative so it cannot enter the
        # required brief queue.
        return True
    if candidate_tier == "strong" and (
        has_report_evidence
        or profile.trusted_direct_action
        or candidate_event_kind in {
            "app_store_trust",
            "company_org",
            "developer_tool",
            "hardware_market",
            "legal_antitrust",
            "os_app",
            "regional_regulation",
            "retail_store",
            "security_privacy",
            "wallet_feature",
        }
    ):
        return True
    if is_apple_developer_tool_story(text):
        return True
    if is_official_apple_accessory_market_story(text):
        return True
    if is_official_apple_refurbished_product_story(text):
        return True
    if is_unreleased_beats_hardware_story(text):
        return True
    if is_apple_books_or_store_platform_trust_story(candidate.title, text):
        return True
    if is_apple_hardware_product_launch_story(text, candidate.title):
        return True
    if is_broad_apple_product_roadmap_story(text):
        return True
    if is_apple_company_org_change_story(text):
        return True
    if is_apple_executive_government_meeting_story(candidate.title, text):
        return True
    if is_apple_executive_company_story(text):
        return True
    if is_apple_strategic_transaction_story(text):
        return True
    if candidate_event_kind == "service_content":
        return True
    if is_apple_research_candidate(text):
        return True
    if is_apple_health_data_research_candidate(text):
        return True
    if is_apple_product_applied_research_story(candidate.title, text):
        return True
    if is_apple_product_driven_market_forecast_story(candidate.title, text):
        return True
    if is_concrete_apple_event_operations_story(candidate.title, text):
        return True
    if is_apple_os_feature_or_summary_story(text):
        return True
    if is_messages_platform_candidate(text):
        return True
    if candidate_event_kind == "ecosystem_interop":
        return True
    if is_third_party_platform_availability_candidate(text):
        return True
    if is_routine_third_party_apple_platform_story(text):
        return True
    official_service_promo = (
        score_terms(
            lower_text,
            ["apple card", "apple pay", "app store", "apple music", "apple tv", "icloud"],
        )
        > 0
        and score_terms(
            lower_text,
            ["promo", "promotion", "offer", "cash back", "daily cash", "free trial"],
        )
        > 0
    )
    if official_service_promo:
        return True
    if action_score <= 0 and strong_score <= 0 and source.name != "Apple Newsroom":
        return False
    if exclude_score > 0 and strong_score <= 0:
        return False
    return True


def parse_datetime_value(raw_value: str, default_tz_name: str) -> datetime | None:
    return article_processing.parse_datetime_value(raw_value, default_tz_name, current_year=lambda: datetime.now().year)


def fact_noise(value: str) -> bool:
    lower = value.lower()
    if _compiled_rule(r"^as\s+a\s+side\s+note\b", 0).match(lower) and _compiled_rule(r"\breminiscent\s+of\b", 0).search(lower):
        return True
    if _compiled_rule(r"^(?:once you['’]re done[, ]+)?(?:make sure you|be sure to)\s+(?:catch|read|check out)\b", 0).match(lower) and _compiled_rule(r"\b(?:review|coverage|article|guide)\b", 0).search(lower):
        return True
    if (
        len(value) < 140
        and _compiled_rule(r"^[*•-]?\s*(?:buy|shop|save|get)\b", 0).match(lower)
        and _compiled_rule(r"\b(?:discount|deal|off|refurbished|amazon|best buy)\b", 0).search(lower)
    ):
        return True
    if _compiled_rule(r"\blet us know\b.*\b(?:comments?|tips@|below)\b", 0).search(lower):
        return True
    if (
        _compiled_rule(r"^(?:click|tap|press)\b", 0).match(lower)
        and _compiled_rule(r"\b(?:icon|button|menu|settings|toggle|tab|dropdown|beta updates)\b", 0).search(lower)
    ):
        return True
    if (
        _compiled_rule(r"^(?:from\s+the\s+(?:dropdown|menu)|open\s+(?:the\s+)?(?:settings|system settings)|"
            r"go\s+to\s+(?:settings|system settings)|navigate\s+to)\b", 0).match(lower)
        and _compiled_rule(r"\b(?:select|choose|click|tap|settings|menu|dropdown)\b", 0).search(lower)
    ):
        return True
    if _compiled_rule(r"apple @ work is exclusively brought to you|about apple @ work|request your extended trial|\bmosyle\b", re.I).search(lower):
        return True
    if _compiled_rule(r"广告声明|文内含有的对外跳转链接|it之家所有文章均包含本声明", re.I).search(lower):
        return True
    if _compiled_rule(r"due to the political or social nature of the discussion|political news forum|posting is limited to forum members", re.I).search(lower):
        return True
    if _compiled_rule(r"当前位置[:：]|当前位置：首页|相关阅读[:：]|相关文章[:：]|延伸阅读[:：]|更多阅读[:：]|豫icp备|icp备|公网安备", re.I).search(lower):
        return True
    if _compiled_rule(r"^apple (?:music|arcade|news\+|tv\+|one(?: bundle)?)\s+[–-]\s*[$￥¥€£]?\d", 0).match(lower) and "after free trial" in lower:
        return True
    if (
        _compiled_rule(r"\bapple (?:music|arcade|news\+|tv\+?|one(?: bundle)?)\b", 0).search(lower)
        and _compiled_rule(r"\b(?:available|requires|subscription|sign up|per month|free trial)\b", 0).search(lower)
        and _compiled_rule(r"(?:[$€£¥￥]\d|\bfree trial\b|\bsubscription\b)", 0).search(lower)
        and score_terms(
            lower,
            [
                "cash back",
                "chase",
                "credit card",
                "daily cash",
                "discount",
                "offer",
                "perk",
                "promo",
                "promotion",
                "reserve",
                "sapphire",
                "优惠",
                "折扣",
                "促销",
                "权益",
            ],
        )
        == 0
    ):
        return True
    if (
        _compiled_rule(r"\b(?:amazon|amzn\.to|best buy)\b", 0).search(lower)
        and _compiled_rule(r"\b(?:priced from|currently priced|reg\.|record low|discount|deal)\b", 0).search(lower)
    ):
        return True
    if len(value) < 140 and _compiled_rule(r"^《.+》$", 0).match(value.strip()):
        return True
    if (
        len(value) < 120
        and not _compiled_rule(r"[，,。；;]", 0).search(value)
        and score_terms(
            lower,
            ["首发", "铺路", "嘲笑", "反转", "退场", "曝光", "前瞻", "发布"],
        )
        > 0
        and (effective_apple_term_score(value) > 0 or loose_apple_product_marker(value))
    ):
        return True
    if (
        len(value) < 120
        and not _compiled_rule(r"[，,。；;]", 0).search(value)
        and (effective_apple_term_score(value) > 0 or loose_apple_product_marker(value))
        and ("！" in value or "!" in value)
        and ("：" in value or ":" in value)
    ):
        return True
    if (
        len(value) < 100
        and not _compiled_rule(r"[，,。；;]", 0).search(value)
        and (effective_apple_term_score(value) > 0 or loose_apple_product_marker(value))
        and ("：" in value or ":" in value)
    ):
        return True
    if _compiled_rule(r"^[a-z]{3} [a-z]{3} \d{2} \d{4}, \d{1,2}:\d{2} [ap]m [a-z]{3}\b", 0).match(lower) and "minute read" in lower:
        return True
    if lower.startswith(("worth checking out", "related:", "related stories")):
        return True
    if (
        len(value) < 140
        and not _compiled_rule(r"[.!?。！？]$", 0).search(value)
        and _compiled_rule(r"\b(will reportedly|reportedly add|here'?s|every new feature|new features to|what rumors say|"
            r"coming soon|launch later|set to launch|feature release timing)\b", 0).search(lower)
    ):
        return True
    if len(value) < 120 and lower.endswith(", more") and "more than" not in lower:
        return True
    if len(value) < 120 and lower.endswith(" and more") and "more than" not in lower:
        return True
    if len(value) < 80 and _compiled_rule(r"subscribe|advertisement|cookie|privacy policy|share article|"
        r"media text of this article|read more|related stories|open menu|login register", 0).search(lower):
        return True
    if newsletter_navigation_noise(value):
        return True
    if lower.startswith(("share article", "media text of this article", "advertisement", "subscribe")):
        return True
    return False


def data_value_count(value: str) -> int:
    return sum(1 for match in DATA_VALUE_PATTERN.finditer(value) if _compiled_rule(r"\d", 0).search(match.group(0)))


def is_key_fact(tag: str, value: str) -> bool:
    numbers = data_value_count(value)
    is_short_list_fact = (
        tag in {"li", "tr"}
        and len(value) >= 20
        and numbers > 0
        and (effective_apple_term_score(value) > 0 or loose_apple_product_marker(value))
    )
    if (len(value) < 35 and not is_short_list_fact) or fact_noise(value):
        return False
    has_context = score_terms(value, FACT_CONTEXT_TERMS) > 0
    has_feature_list = FEATURE_LIST_PATTERN.search(value) is not None
    has_list_shape = tag in {"li", "tr"} or len(_compiled_rule(r"[,;；、，]", 0).findall(value)) >= 2
    if is_short_list_fact:
        return True
    if numbers >= 2:
        return True
    if numbers and (has_context or has_list_shape or has_feature_list):
        return True
    if tag in {"li", "tr"} and has_context and (has_feature_list or len(value) <= 500):
        return True
    if tag in {"li", "tr"} and len(value) <= 500 and (has_feature_list or has_list_shape):
        return True
    if has_context and has_feature_list and has_list_shape:
        return True
    return False


def is_contextual_structured_list_fact(tag: str, value: str, title: str, context: str) -> bool:
    """Keep compact table-like rows whose Apple subject is declared by the list intro."""
    if tag not in {"li", "tr"} or not (20 <= len(value) <= 320):
        return False
    if data_value_count(value) < 2 or fact_noise(value):
        return False
    if effective_apple_term_score(title) <= 0 and not loose_apple_product_marker(title):
        return False
    if score_terms(
        context,
        [
            "details below",
            "details are as follows",
            "following prices",
            "following plans",
            "the following",
            "详情如下",
            "以下是详情",
            "如下",
            "分别为",
            "价格",
            "涨价",
            "费用",
            "售价",
            "套餐",
            "订阅",
        ],
    ) <= 0:
        return False
    labelled_row = _compiled_rule(r"^[^.!?。！？:：]{1,48}[:：]", 0).match(value) is not None
    price_transition = bool(
        _compiled_rule(r"(?:→|->|\bto\b|涨\s*\d|降\s*\d)", re.I).search(value)
        and _compiled_rule(r"[$€£¥￥]\s?\d|\d+(?:\.\d+)?\s*(?:美元|元|人民币|日元|欧元|英镑)", 0).search(value)
    )
    return labelled_row and (price_transition or data_value_count(value) >= 3)


def key_fact_min_chars(value: str) -> int:
    cleaned = clean_fact_text(value)
    compact_price_row = bool(
        _compiled_rule(r"^[^.!?。！？:：]{1,48}[:：]", 0).match(cleaned)
        and data_value_count(cleaned) >= 2
        and _compiled_rule(r"(?:→|->|\bto\b|涨\s*\d|降\s*\d)", re.I).search(cleaned)
        and _compiled_rule(r"[$€£¥￥]\s?\d|\d+(?:\.\d+)?\s*(?:美元|元|人民币|日元|欧元|英镑)", 0).search(cleaned)
    )
    if (
        20 <= len(cleaned) < 35
        and data_value_count(cleaned) > 0
        and (
            effective_apple_term_score(cleaned) > 0
            or loose_apple_product_marker(cleaned)
            or compact_price_row
        )
    ):
        return 20
    return 35


def extract_key_facts(text: str, title: str, source_name: str) -> list[str]:
    limit = MAX_OFFICIAL_KEY_FACTS if source_name in OFFICIAL_FACT_SOURCES else MAX_KEY_FACTS
    facts: list[str] = []
    seen: set[str] = set()
    title_text = clean_fact_text(title)
    market_report = collection.market_summary_needs_detail(title_text)
    list_context = ""
    for tag, unit in extract_text_units(text):
        cleaned = clean_fact_text(unit)
        if not cleaned:
            continue
        if tag not in {"li", "tr"}:
            list_context = cleaned
        if title_text and cleaned.lower() == title_text.lower():
            continue
        for candidate in split_fact_candidates(tag, cleaned):
            if (
                source_name not in OFFICIAL_FACT_SOURCES
                and tag in {"h2", "h3"}
                and data_value_count(candidate) == 0
            ):
                continue
            if source_apple_invitation_fact(candidate) or (market_report and source_market_measurement_frame(title_text, '', (candidate,))) or is_key_fact(tag, candidate) or is_contextual_structured_list_fact(
                tag,
                candidate,
                title_text,
                list_context,
            ):
                min_chars = 20 if tag in {"li", "tr"} else key_fact_min_chars(candidate)
                add_unique_text(facts, seen, candidate, min_chars=min_chars)
                if len(facts) >= limit:
                    return facts
    if not facts:
        identity = title_led_identity(title, extract_summary(text, ""))
        if (
            identity.action_owner == "apple"
            and identity.content_form == "news"
            and "official-communication" in identity.title_actions
        ):
            # Official communications may convey important narrative facts
            # without quantities. Use only cleaned substantive body units.
            for tag, unit in extract_text_units(text):
                cleaned = clean_fact_text(unit)
                if tag in {"p", "blockquote"} and not fact_noise(cleaned):
                    add_unique_text(facts, seen, cleaned)
                    if len(facts) >= limit:
                        break
    return facts


def extract_summary(text: str, fallback: str) -> str:
    scoped_text = article_scope(text)
    parts: list[str] = []
    seen: set[str] = set()
    description = meta_content(
        text,
        ["og:description", "twitter:description", "description", "Description"],
    )
    if description:
        cleaned_description = source_description_without_editorial_prefix(text, description)
        if cleaned_description:
            parts.append(cleaned_description)
            seen.add(cleaned_description.lower()[:120])
    for match in _compiled_rule(r"(?is)<p[^>]*>(.*?)</p>", 0).finditer(scoped_text):
        cleaned = strip_tags(match.group(1))
        if (len(cleaned) >= 60 and not fact_noise(cleaned)
                and not _compiled_rule(r"subscribe|advertis|open menu|front page|login register|"
            r"visit forums|roundups|buyer'?s guide|direct messages|anonymous form|"
            r"广告声明|文内含有的对外跳转链接|IT之家所有文章均包含本声明|"
            r"当前位置[:：]|相关阅读[:：]|相关文章[:：]|延伸阅读[:：]|ICP备|公网安备", re.I).search(cleaned)):
            key = cleaned.lower()[:120]
            if key not in seen:
                parts.append(cleaned)
                seen.add(key)
        if len(parts) >= 5:
            break
    if parts:
        return " ".join(parts)
    return strip_tags(fallback)


def _topic_boundary_facets_for_text(title: str, summary: str = "") -> frozenset[str]:
    """Return concrete event-boundary facets that should not be crossed by background text."""
    facets = effective_topic_facets(primary_topic_facets(title, summary))
    boundary_facets = independent_splittable_topic_facets(facets)
    if not boundary_facets:
        boundary_facets = facets & (SPLITTABLE_TOPIC_FACETS | SUMMARY_LEVEL_EVENT_MERGE_FACETS)
    return frozenset(boundary_facets - BROAD_TOPIC_FACETS)


@lru_cache(maxsize=16384)
def cached_topic_boundary_facets_for_text(title: str, summary: str = "") -> frozenset[str]:
    return _topic_boundary_facets_for_text(title, summary)


def topic_boundary_facets_for_text(title: str, summary: str = "") -> set[str]:
    return set(cached_topic_boundary_facets_for_text(title, summary))


def topic_boundary_facets_conflict(primary_facets: set[str], secondary_facets: set[str]) -> bool:
    if not primary_facets or not secondary_facets:
        return False
    return not splittable_topic_facets_compatible(primary_facets, secondary_facets)


def discovery_text_conflicts_with_detail_topic(
    detail_title: str,
    detail_summary: str,
    discovery_text: str,
) -> bool:
    if not discovery_text:
        return False
    detail_facets = topic_boundary_facets_for_text(detail_title, detail_summary)
    discovery_facets = topic_boundary_facets_for_text("", discovery_text)
    return topic_boundary_facets_conflict(detail_facets, discovery_facets)


def detail_page_identity_rejects_discovery_text(
    detail_title: str,
    detail_summary: str,
    discovery_text: str,
) -> bool:
    """Prevent listing metadata from changing a successfully parsed detail-page subject."""
    if not discovery_text:
        return False
    detail_scope = title_and_lead_scope(detail_title, detail_summary, limit=1200)
    if effective_apple_term_score(detail_scope) <= 0 and effective_apple_term_score(discovery_text) > 0:
        return True
    return bool(
        is_non_apple_primary_subject_with_incidental_apple_context(detail_title, detail_scope)
        or is_multi_brand_comparison_led_market_story(detail_title, detail_scope)
        or is_competitor_launch_against_apple_story(detail_title, detail_scope)
        or is_third_party_app_or_service_status_story(detail_title, detail_scope)
    )


def safe_discovery_text_for_detail(detail_title: str, detail_summary: str, discovery_text: str) -> str:
    if detail_page_identity_rejects_discovery_text(detail_title, detail_summary, discovery_text):
        return ""
    if discovery_text_conflicts_with_detail_topic(detail_title, detail_summary, discovery_text):
        return ""
    return discovery_text


def safe_combine_detail_and_discovery_summary(
    detail_title: str,
    detail_summary: str,
    discovery_summary: str,
) -> str:
    return combine_summaries(
        detail_summary,
        safe_discovery_text_for_detail(detail_title, detail_summary, discovery_summary),
    )


def detail_summary_needs_discovery_enrichment(
    detail_summary: str,
    key_facts: list[str] | None = None,
) -> bool:
    """Use listing text only when a successful detail parse is genuinely empty."""
    cleaned = clean_sentence(detail_summary)
    return len(cleaned) < 80 and not any(clean_sentence(fact) for fact in (key_facts or []))


def safe_context_for_detail_article(
    is_roundup: bool,
    detail_title: str,
    detail_summary: str,
    candidate_context: str,
) -> str:
    if is_roundup:
        return ""
    return safe_discovery_text_for_detail(detail_title, detail_summary, candidate_context)


def hardware_rumor_supporting_fact_compatible(primary_facets: set[str], fact_facets: set[str]) -> bool:
    hardware_primary_facets = IPHONE_HARDWARE_RUMOR_TOPIC_FACETS | {
        "apple-future-product-price-forecast",
        "apple-product-price-increase",
        "foldable-iphone-render-leak",
        "foldable-iphone-successor-roadmap",
        "foldable-iphone-supply-chain",
        "iphone-component-cost-forecast",
    }
    hardware_supporting_fact_facets = hardware_primary_facets | {
        "apple-chip-process-roadmap",
        "apple-chip-roadmap",
        "iphone-chip-roadmap",
        "iphone-launch-timing",
        "iphone-memory-price-forecast",
    }
    return bool(primary_facets & hardware_primary_facets) and bool(
        fact_facets & hardware_supporting_fact_facets
    ) and not bool(
        fact_facets
        & {
            "apple-product-data-leak",
            "apple-product-data-leak-enforcement",
            "apple-product-data-leak-specs",
            "ios-signing-status",
        }
    )


def key_fact_topic_compatible_with_primary(primary_facets: set[str], fact_facets: set[str]) -> bool:
    primary_versions = {facet for facet in primary_facets if facet.startswith("os-release-version-")}
    fact_versions = {facet for facet in fact_facets if facet.startswith("os-release-version-")}
    primary_platforms = {facet for facet in primary_facets if facet.startswith("platform-")}
    fact_platforms = {facet for facet in fact_facets if facet.startswith("platform-")}
    if primary_versions and fact_versions and primary_versions.isdisjoint(fact_versions):
        return False
    if primary_platforms and fact_platforms and primary_platforms.isdisjoint(fact_platforms):
        return False
    if not topic_boundary_facets_conflict(primary_facets, fact_facets):
        return True
    return hardware_rumor_supporting_fact_compatible(primary_facets, fact_facets)


