def has_direct_iphone_product_title_subject(title: str) -> bool:
    from apple_news_core.event_identity import has_direct_iphone_product_title_subject as source_title_subject
    return source_title_subject(title)


def is_apple_platform_media_format_compatibility_story(title: str, text: str) -> bool:
    """A device list for an OS image format remains software compatibility."""
    opening = " ".join(_compiled_rule(r"(?<=[.!?])\s+|[。！？]", 0).split(text, 2)[:2])
    return bool(
        _compiled_rule(r"\bRAW\b.{0,24}(?:support|compatib)|(?:扩展|新增).{0,14}\bRAW\b.{0,8}(?:支持|兼容)", re.I).search(title)
        and _compiled_rule(r"\bApple\b.{0,65}(?:updated?|revised?)\b.{0,45}\bsupport\b|苹果.{0,24}(?:更新|修订).{0,18}支持文档", re.I).search(opening)
        and _compiled_rule(r"\b(?:iOS|iPadOS|macOS|visionOS)\b|操作系统|系统级", re.I).search(text)
    )


def is_apple_named_software_control_scope_story(title: str, text: str) -> bool:
    """A revised list of supported editing controls is a software action."""
    opening = " ".join(_compiled_rule(r"(?<=[.!?])\s+|[。！？]", 0).split(text, 2)[:2])
    return bool(
        _compiled_rule(r"\bcontrols?\b|控件", re.I).search(title)
        and _compiled_rule(r"\b(?:clarif(?:y|ies|ied)|revis(?:e|ed)|correct(?:s|ed)?)\b|(?:修订|更正|澄清)", re.I).search(title)
        and _compiled_rule(r"\b(?:support\s+page|support\s+document|supported\s+model|available\s+only|require)\b|(?:支持文档|仅限|仅支持|兼容范围)", re.I).search(text)
        and _compiled_rule(r"\bApple\b.{0,70}\b(?:revis(?:ed|es)?|updated?|clarif(?:ied|ies))\b|苹果.{0,28}(?:更新|修订|澄清)", re.I).search(opening)
        and _compiled_rule(r"\b(?:software|editing|camera\s+app)\b|(?:软件|编辑|相机应用)", re.I).search(text)
    )


def is_direct_iphone_hardware_spec_rumor_story(title: str, text: str) -> bool:
    from apple_news_core.event_identity import current_iphone_report_passages
    if is_apple_platform_media_format_compatibility_story(title, text):
        return False
    if is_apple_named_software_control_scope_story(title, text):
        return False
    # Explicit contextual specifications are not the source's reported action.
    title_lower = title.lower()
    if not has_direct_iphone_product_title_subject(title):
        return False
    if is_non_actionable_recap_title(title) or is_non_apple_comparison_title(title):
        return False
    semantic_identity = title_led_identity(title, text)
    if semantic_identity.scope != "apple-direct" or semantic_identity.content_form != "news":
        return False
    if is_rumor_feature_recap_without_new_reporting(title, text):
        return False
    competitor_in_title = score_terms(
        title_lower,
        ["android", "galaxy", "samsung", "huawei", "xiaomi", "redmi", "oppo", "vivo", "honor", "pixel", "安卓", "三星", "华为", "小米", "红米", "荣耀"],
    ) > 0
    supplier_or_component_context = score_terms(
        title_lower,
        [
            "will use",
            "to use",
            "use samsung",
            "supplier",
            "supply",
            "sensor",
            "image sensor",
            "component",
            "搭载",
            "采用",
            "供应",
            "供应商",
            "图像传感器",
            "传感器",
            "组件",
        ],
    ) > 0
    if competitor_in_title and not supplier_or_component_context:
        return False
    hardware_details = [
        "battery capacity",
        "battery",
        "mah",
        "sim",
        "esim",
        "dynamic island",
        "face id",
        "camera",
        "camera control",
        "variable aperture",
        "packaging",
        "retail box",
        "color",
        "colour",
        "finish",
        "display",
        "screen",
        "chip",
        "modem",
        "baseband",
        "nand",
        "storage",
        "flash",
        "qlc",
        "tlc",
        "sensor",
        "容量",
        "电池容量",
        "包装盒",
        "屏幕",
        "显示屏",
        "双屏",
        "双摄",
        "电池",
        "实体 sim",
        "实体sim",
        "灵动岛",
        "配色",
        "颜色",
        "摄像头",
        "前摄",
        "后摄",
        "相机",
        "可变光圈",
        "芯片",
        "调制解调器",
        "基带",
        "闪存",
        "存储",
        "传感器",
    ]
    reporting = [
        "rumor",
        "rumors",
        "leak",
        "leaks",
        "leaked",
        "revealed",
        "published",
        "posted",
        "report",
        "reported",
        "said",
        "heard",
        "reportedly",
        "coming",
        "launching",
        "expected",
        "this fall",
        "blogger",
        "weibo",
        "报告",
        "据了解",
        "公布",
        "曝光",
        "泄露",
        "流出",
        "爆料",
        "消息称",
        "据称",
        "据悉",
        "被曝",
        "透露",
        "即将",
        "将发布",
        "预计",
        "新鲜出炉",
        "显示",
        "博主",
        "社交平台",
    ]
    # A report predicate and its hardware detail must share a current source
    # assertion. Unrelated app announcements cannot qualify device background.
    current_passages = current_iphone_report_passages(title, text, hardware_details=tuple(hardware_details))
    return any(score_terms(passage, hardware_details) > 0
        and score_terms(title + " " + passage, reporting) > 0
        for passage in current_passages)


def is_camera_airpods_hardware_roadmap_story(title: str, text: str) -> bool:
    """Identify a title-led report about Apple developing camera-equipped AirPods."""
    title_lower = title.lower()
    lead = title_and_lead_scope(title, text, limit=1200).lower()
    if score_terms(title_lower, ["airpods", "苹果耳机"]) <= 0:
        return False
    if score_terms(lead, ["camera", "cameras", "camera-equipped", "摄像头", "相机"]) <= 0:
        return False
    if score_terms(
        lead,
        [
            "developing",
            "development",
            "working on",
            "could arrive",
            "may arrive",
            "expected",
            "reportedly",
            "roadmap",
            "launch",
            "代码",
            "开发",
            "研发",
            "预计",
            "有望",
            "将配备",
            "路线图",
            "发布",
        ],
    ) <= 0:
        return False
    return score_terms(
        title_lower,
        [
            "camera",
            "cameras",
            "camera-equipped",
            "with cameras",
            "摄像头",
            "相机",
        ],
    ) > 0


