def is_third_party_app_vulnerability_without_apple_platform_flaw(title: str, text: str) -> bool:
    """Keep a third-party app's own sandbox failure separate from macOS flaws."""
    lead = title_and_lead_scope(title, text, limit=1600).lower()
    if is_direct_apple_security_bulletin_research_story(title, lead):
        return False
    if score_terms(lead, ["mac", "macos", "mac files", "mac 文件", "mac 用户"]) <= 0:
        return False
    if score_terms(
        lead,
        [
            "vulnerability",
            "flaw",
            "exploit",
            "sandbox escape",
            "escaped sandbox",
            "full access to all files",
            "漏洞",
            "沙箱逃逸",
            "突破沙箱",
            "任意 mac 文件",
            "读写任意",
        ],
    ) <= 0:
        return False
    third_party_subject = score_terms(
        lead,
        [
            "third-party app",
            "third-party agent",
            "agent app",
            "claude cowork",
            "linux vm",
            "linux virtual machine",
            "its own sandbox",
            "app's sandbox",
            "应用自身",
            "第三方应用",
            "第三方智能体",
            "智能体应用",
            "linux 虚拟机",
            "自身沙箱",
        ],
    ) > 0
    if not third_party_subject:
        return False
    direct_platform_flaw = score_terms(
        lead,
        [
            "macos vulnerability",
            "macos flaw",
            "macos sandbox vulnerability",
            "apple sandbox vulnerability",
            "gatekeeper",
            "tcc",
            "code signing",
            "bootrom",
            "secure-rom",
            "apple security bulletin",
            "apple patched",
            "apple fixed",
            "苹果安全公告",
            "macos 系统漏洞",
            "macos 沙箱漏洞",
            "代码签名",
            "苹果修复",
            "苹果发布补丁",
        ],
    ) > 0
    return not direct_platform_flaw


def is_apple_platform_executable_replacement_attack_story(title: str, text: str) -> bool:
    lead = title_and_lead_scope(title, text, limit=1500).lower()
    if not is_direct_apple_platform_security_impact_story(title, lead):
        return False
    executable_score = score_terms(
        lead,
        [
            "trusted app",
            "trusted application",
            "app executable",
            "application executable",
            "replace executable",
            "swapped out",
            "swap out",
            "受信任应用",
            "应用可执行文件",
            "替换可执行文件",
            "替换应用",
        ],
    )
    if executable_score > 0:
        return True
    return bool(
        _compiled_rule(r"\b(?:trusted\s+)?mac\s+apps?\b", 0).search(lead)
        and _compiled_rule(r"\b(?:swap(?:ped)?\s+out|replace(?:d|ment)?)\b", 0).search(lead)
    ) or bool(
        _compiled_rule(r"受信任.{0,10}(?:mac\s*)?应用", 0).search(lead)
        and _compiled_rule(r"替换.{0,10}(?:可执行文件|应用)", 0).search(lead)
    )


