def is_third_party_ai_model_release_for_apple_device_without_apple_action(title: str, text: str) -> bool:
    lower = title_and_lead_scope(title, text, limit=1400).lower()
    if is_apple_on_device_ai_model_compression_story(lower):
        return False
    if has_apple_first_party_release_context(title.lower()):
        return False
    if score_terms(
        lower,
        [
            "ai model",
            "large language model",
            "llm",
            "open-source model",
            "prismml",
            "prisml",
            "bonsai",
            "qwen",
            "ai 模型",
            "大模型",
            "开源模型",
            "人工智能模型",
        ],
    ) <= 0:
        return False
    if score_terms(
        title.lower(),
        ["releases", "released", "launches", "launched", "debuts", "unveils", "发布", "推出", "登场", "上线"],
    ) <= 0:
        return False
    runtime_pattern = (
        r"\b(?:run|runs|running)\b.{0,55}\b(?:iphone|ipad|mac(?:book)?)\b|"
        r"\b(?:iphone|ipad|mac(?:book)?)\b.{0,55}\b(?:run|runs|running)\b|"
        r"(?:iphone|ipad|mac(?:book)?|苹果设备).{0,55}(?:上运行|可运行|本地运行|端侧运行)"
    )
    return bool(
        re.search(runtime_pattern, lower)
        or score_terms(lower, ["apple devices", "on-device", "on device", "本地运行", "端侧运行"]) > 0
    )


def is_iphone_component_cost_forecast_story(text: str) -> bool:
    lower = text.lower()
    headline = lower[:260]
    if score_terms(headline, ["android", "安卓"]) > 0 and score_terms(headline, ["iphone 18 pro max", "iphone18 pro max"]) <= 0:
        return False
    if score_terms(lower, ["iphone 18 pro max", "iphone18 pro max", "苹果 iphone 18 pro max"]) <= 0:
        return False
    if score_terms(lower, ["component cost", "component costs", "bill of materials", "bom", "materials cost", "物料清单", "物料成本", "组件成本", "成本"]) <= 0:
        return False
    return score_terms(lower, ["counterpoint", "nand", "dram", "memory", "storage", "2nm", "packaging", "$300", "300", "内存", "存储", "闪存", "封装"]) > 0


def is_title_led_iphone_component_cost_forecast_story(title: str, text: str) -> bool:
    """Match component-cost analysis only when cost is the title's Apple action."""
    title_lower = title.lower()
    if score_terms(
        title_lower,
        ["iphone 18", "iphone18", "iphone air", "iphone ultra", "苹果 iphone"],
    ) <= 0:
        return False
    if score_terms(
        title_lower,
        [
            "component cost",
            "bill of materials",
            "bom cost",
            "cost share",
            "成本占",
            "吞噬利润",
            "物料成本",
            "组件成本",
        ],
    ) <= 0:
        return False
    scope = title_and_lead_scope(title, text, limit=1000).lower()
    return score_terms(
        scope,
        ["memory", "storage", "dram", "nand", "flash", "内存", "存储", "闪存", "封装"],
    ) > 0


