def is_carplay_platform_feature_story(text: str) -> bool:
    lower = text.lower()
    if score_terms(lower, ["carplay"]) <= 0:
        return False
    platform_context_score = score_terms(
        lower,
        [
            "ios",
            "ios update",
            "ios release",
            "wwdc",
            "developer beta",
            "public beta",
            "apple unveiled",
            "apple introduced",
            "apple added",
            "apple is allowing",
            "苹果 ios",
            "苹果推出",
            "苹果新增",
            "开发者测试版",
            "公测版",
        ],
    )
    feature_action_score = score_terms(
        lower,
        OS_FEATURE_ACTION_TERMS
        + STRONG_NEWS_ACTION_TERMS
        + [
            "feature",
            "features",
            "enhancement",
            "enhancements",
            "interface",
            "siri",
            "mini player",
            "conversation mode",
            "airplay",
            "route sharing",
            "media app upgrades",
            "功能",
            "升级",
            "界面",
            "路线共享",
            "导航",
        ],
    )
    third_party_primary_score = score_terms(
        lower,
        [
            "spotify",
            "google maps",
            "waze",
            "third-party app",
            "third party app",
            "car maker",
            "automaker",
            "车企",
            "第三方应用",
        ],
    )
    apple_platform_score = score_terms(lower, ["apple", "苹果", "siri", "apple music", "apple tv", "podcasts"])
    return (
        platform_context_score > 0
        and feature_action_score > 0
        and (apple_platform_score > 0 or score_terms(lower, ["ios"]) > 0)
        and not (
            third_party_primary_score > 0
            and score_terms(lower, ["ios", "apple introduced", "apple added", "苹果新增"]) == 0
        )
    )


def is_apple_owned_brand_engineering_strategy_story(title: str, text: str) -> bool:
    """Keep technical Apple-owned brand reporting distinct from promotions."""
    title_lower = title.lower()
    lead = title_and_lead_scope(title, text, limit=1500).lower()
    if not (
        score_terms(title_lower, ["beats"]) > 0
        and score_terms(
            title_lower,
            ["lab", "laboratory", "engineering", "r&d", "研发", "实验室", "工程实验室"],
        )
        > 0
    ):
        return False
    apple_ownership_or_engineering = score_terms(
        lead,
        [
            "apple-owned",
            "apple acquired",
            "apple hardware engineering",
            "apple's engineering resources",
            "apple’s engineering resources",
            "apple's vice president of hardware engineering",
            "apple vice president of hardware engineering",
            "苹果旗下",
            "苹果收购",
            "被苹果公司收购",
            "加入苹果",
            "苹果硬件工程",
            "苹果公司硬件工程",
        ],
    ) > 0
    technical_or_strategy = score_terms(
        lead,
        [
            "anechoic chamber",
            "anechoic chambers",
            "engineering facility",
            "engineering resources",
            "laboratory",
            "laboratories",
            "product strategy",
            "developed to complement",
            "dual ecosystem",
            "separate brand",
            "reliability testing",
            "wireless testing",
            "quality testing",
            "returned products",
            "研发实验室",
            "工程实验室",
            "实验室",
            "消声室",
            "产品策略",
            "可靠性测试",
            "无线测试",
            "质量测试",
        ],
    ) > 0
    return apple_ownership_or_engineering and technical_or_strategy


def is_first_party_service_history_without_new_action(title: str, text: str) -> bool:
    """Recognize service retrospectives without treating current changes as history."""
    title_lower = title.lower().strip()
    if not _compiled_rule(r"^how\s+.{2,48}\s+(?:became|evolved\s+into)\s+", 0).match(title_lower):
        return False
    if score_terms(
        title_lower,
        ["icloud", "apple music", "apple tv", "app store", "apple books", "shazam", "apple arcade"],
    ) <= 0:
        return False
    current_action = score_terms(
        title_lower,
        ["launches", "releases", "adds", "changes", "raises", "expands", "推出", "发布", "新增", "调整", "涨价", "扩展"],
    ) > 0
    return not current_action


def os_feature_component_facets_from_text(text: str) -> set[str]:
    lower = text.lower()
    lead = lower[:700]
    facets: set[str] = set()
    if (
        not is_iphone_photography_awards_story(lower)
        and
        score_terms(
            lower,
            [
                "performance optimization",
                "performance optimizations",
                "faster",
                "speed up",
                "speed improvements",
                "app launch",
                "launch faster",
                "load faster",
                "airdrop transfers",
                "底层优化",
                "性能优化",
                "提速",
                "启动提速",
                "加载提速",
                "隔空投送",
            ],
        )
        > 0
        and score_terms(lead, ["ios", "ipados", "macos", "watchos", "visionos"]) > 0
        and score_terms(lower, ["up to", "ways", "percent", "%", "30%", "70%", "80%", "40+", "40 多", "多项", "最高"]) > 0
    ):
        facets.add("system-performance-optimization")
