def is_future_apple_product_price_forecast_story(text: str, title: str = "") -> bool:
    headline_scope = (title or text[:220]).lower()
    if effective_apple_term_score(headline_scope) <= 0 and score_terms(headline_scope, ["iphone", "ipad", "mac"]) <= 0:
        return False
    future_product_score = score_terms(
        headline_scope,
        [
            "iphone 18",
            "iphone 19",
            "iphone ultra",
            "foldable iphone",
            "folding iphone",
            "iphone fold",
            "next iphone",
            "future iphone",
            "2027 iphone",
            "2028 iphone",
            "iPhone 18".lower(),
            "iPhone Ultra".lower(),
            "折叠屏 iphone",
            "折叠 iphone",
            "折叠屏手机",
            "下一代 iphone",
            "未来 iphone",
            "明年 iphone",
            "万元机",
        ],
    )
    if _compiled_rule(r"苹果\s*\d{2}(?:\s*(?:系列|pro|max|e|air))?", re.I).search(headline_scope):
        future_product_score += 1
    if future_product_score <= 0:
        return False
    if score_terms(
        headline_scope,
        [
            "price not announced",
            "pricing not announced",
            "price has not been announced",
            "price hasn't been announced",
            "price remains unknown",
            "pricing remains unknown",
            "只剩价格还没公布",
            "价格还没公布",
            "价格尚未公布",
            "价格未公布",
            "售价尚未公布",
            "售价未公布",
        ],
    ) > 0:
        return False
    price_anchor_score = score_terms(
        headline_scope,
        [
            "starting price",
            "expected to cost",
            "estimated price",
            "estimated pricing",
            "forecast price",
            "forecast pricing",
            "price forecast",
            "pricing forecast",
            "priced at",
            "price",
            "pricing",
            "more expensive",
            "涨价",
            "定价",
            "售价",
            "起售价",
            "起步价",
            "价格",
            "万元机",
        ],
    )
    monetary_amount = bool(_compiled_rule(r"(?:[$￥¥]\s*\d|\d[\d,.]*\s*(?:dollars?|usd|美元|元|万元|人民币))", 0).search(headline_scope))
    # A start can be a date or a production stage. Only a financial noun or
    # amount supports a price forecast; speculative wording alone does not.
    if price_anchor_score <= 0 and not monetary_amount:
        return False
    if monetary_amount:
        instrument_amount = bool(_compiled_rule(r"补贴|补助|优惠券|返现|免息|分期|以旧换新|折抵|"
            r"\b(?:trade[ -]in|subsid(?:y|ies)|instalments?|installments?|financing|coupons?|cashback)\b", re.I).search(headline_scope))
        # A quoted instrument benefit is not the device's own price. Explicit
        # product pricing remains valid even when a platform offer is nearby.
        return price_anchor_score > 0 or not instrument_amount
    return score_terms(
        headline_scope,
        [
            "expected",
            "estimated",
            "forecast",
            "reportedly",
            "rumor",
            "rumored",
            "prediction",
            "消息称",
            "爆料",
            "预计",
            "预估",
            "预测",
            "或",
            "将",
        ],
    ) > 0


