def is_apple_legal_proceeding_story(text: str) -> bool:
    lower = text.lower()
    if effective_apple_term_score(lower) <= 0:
        return False
    headline = lower[:320]
    legal_headline_score = score_terms(
        headline,
        [
            "lawsuit",
            "sue",
            "sues",
            "suing",
            "sued",
            "court",
            "filing",
            "complaint",
            "jury trial",
            "trade secret",
            "trade secrets",
            "诉讼",
            "起诉",
            "法院",
            "法庭",
            "陪审团",
            "商业秘密",
        ],
    )
    product_render_headline_score = score_terms(
        headline,
        [
            "foldable iphone",
            "iphone fold",
            "iphone ultra",
            "render",
            "renders",
            "mockup",
            "dummy",
            "prototype",
            "leak",
            "rumor",
            "折叠屏",
            "渲染图",
            "机模",
            "样机",
            "泄露",
            "爆料",
        ],
    )
    if product_render_headline_score > 0 and score_terms(
        headline,
        [
            "released",
            "published",
            "shared",
            "showed",
            "revealed",
            "发布",
            "现身",
            "展示",
            "放出",
            "分享",
        ],
    ) > 0:
        return False
    if legal_headline_score <= 0 and product_render_headline_score > 0:
        return False
    proceeding_score = score_terms(
        lower,
        [
            "lawsuit",
            "sue",
            "sues",
            "suing",
            "sued",
            "court",
            "filing",
            "legal filing",
            "complaint",
            "jury trial",
            "trade secret",
            "trade secrets",
            "co-defendant",
            "lawsuit response",
            "诉讼",
            "起诉",
            "法院",
            "法庭",
            "提交文件",
            "法律文件",
            "陪审团",
            "商业秘密",
        ],
    )
    if proceeding_score <= 0:
        return False
    return score_terms(
        lower,
        [
            "prosser",
            "ramacciotti",
            "epic",
            "masimo",
            "doj",
            "department of justice",
            "cma",
            "cci",
            "fas",
            "apple lawsuit",
            "苹果诉讼",
            "苹果起诉",
        ],
    ) > 0 or proceeding_score >= 2


