def is_third_party_app_or_service_status_story(title: str, text: str) -> bool:
    title_lower = title.lower()
    lower = text.lower()
    combined = f"{title} {text}"
    semantic_identity = title_led_identity(title, text)
    if semantic_identity.title_actions & {"legal", "regulation"}:
        return False
    if is_final_cut_camera_update_story(f"{title} {text}"):
        return False
    if is_apple_creator_studio_story(f"{title} {text}"):
        return False
    if is_direct_iphone_hardware_spec_rumor_story(title, text):
        return False
    if is_foldable_iphone_successor_roadmap_story(f"{title} {text}"):
        return False
    if title_lower.startswith("apple ") or title_lower.startswith("苹果"):
        return False
    if app_store_policy_score(lower) > 0:
        return False
    if score_terms(title_lower, ["apple", "苹果"]) > 0 and score_terms(
        title_lower,
        [
            "regulator",
            "regulation",
            "regulatory",
            "antitrust",
            "fine",
            "fined",
            "lawsuit",
            "sues",
            "sued",
            "court",
            "ruling",
            "appeal",
            "investigation",
            "subpoena",
            "settlement",
            "监管",
            "反垄断",
            "罚款",
            "诉讼",
            "起诉",
            "法院",
            "裁定",
            "判决",
            "上诉",
            "调查",
            "传票",
            "和解",
            "勒令",
        ],
    ) > 0:
        return False
    if is_title_primary_software_system_story(title, combined):
        return False
    if has_first_party_software_title_subject(title) or has_apple_first_party_release_context(text):
        return False
    if score_terms(
        lower,
        [
            "ios",
            "ipados",
            "macos",
            "tvos",
            "iphone",
            "ipad",
            "mac",
            "app store",
            "apple watch",
            "apple tv",
            "vision pro",
            "苹果手机",
            "苹果应用商店",
            "苹果电视",
        ],
    ) <= 0:
        return False
    if score_terms(
        lower,
        [
            "third-party",
            "third party",
            "app",
            "apps",
            "application",
            "client",
            "service",
            "email client",
            "calculator app",
            "utility",
            "workflow",
            "agent",
            "open source",
            "openstreetmap",
            "map app",
            "maps app",
            "第三方",
            "应用",
            "客户端",
            "服务",
            "开源",
            "地图应用",
        ],
    ) <= 0:
        return False
    if score_terms(
        lower,
        [
            "shutting down",
            "shuts down",
            "shutdown",
            "close",
            "closes",
            "closing",
            "discontinue",
            "discontinues",
            "discontinued",
            "sunset",
            "sunsetting",
            "launched",
            "launches",
            "released",
            "updated",
            "brings",
            "gets",
            "expanding to",
            "native",
            "builds",
            "created",
            "停运",
            "关闭",
            "终止",
            "下线",
            "上线",
            "发布",
            "更新",
            "获得",
            "打造",
            "带来",
            "整改",
            "整改公告",
            "发布公告",
            "优先推送",
            "会员服务",
        ],
    ) <= 0:
        return False
    # App Store in an activity description and an updated forum post are
    # not an application update. The object and status belong to one clause.
    local_status = any(
        _compiled_rule(r"\b(?:apps?|applications?|clients?|services?|utilities|workflow|agent)\b(?!\s+store)|应用|客户端|服务|开源", re.I).search(clause)
        and _compiled_rule(r"\b(?:shutting down|shuts down|shutdown|closes?|closing|discontinues?|discontinued|sunset|sunsetting|launched|launches|released|updates?|updated|brings|gets|expanding to|native|builds|created)\b|停运|关闭|终止|下线|上线|发布|更新|获得|打造|带来|整改|优先推送|会员服务", re.I).search(clause)
        for clause in (title, *_compiled_rule(r"(?<=[.!?])\s+|[。！？]", 0).split(text, 0)))
    if not local_status:
        return False
    return score_terms(
        lower,
        [
            "apple acquired",
            "joins apple",
            "apple approved",
            "apple policy",
            "apple requires",
            "苹果收购",
            "加入苹果",
            "苹果批准",
            "苹果政策",
        ],
    ) == 0


