def title_scoped_hardware_product_roadmap_facets(title: str) -> set[str]:
    lower = title.lower()
    if score_terms(
        lower,
        [
            "price",
            "prices",
            "price hike",
            "price hikes",
            "price increase",
            "cost",
            "costs",
            "shipment",
            "shipments",
            "market",
            "trendforce",
            "涨价",
            "调价",
            "价格",
            "成本",
            "出货",
            "市场",
        ],
    ) > 0:
        return set()
    if score_terms(
        lower,
        [
            "launch",
            "launches",
            "release",
            "released",
            "coming",
            "new",
            "refresh",
            "updated",
            "testing",
            "reportedly",
            "spring",
            "fall",
            "2026",
            "2027",
            "推出",
            "发布",
            "新款",
            "更新",
            "测试",
            "春季",
            "秋季",
            "明年",
        ],
    ) <= 0:
        return set()
    families = hardware_product_families_from_text(lower)
    if "macbook" in families:
        families.discard("mac")
    if families == {"macbook"}:
        return {"macbook-product-roadmap"}
    if families == {"ipad"}:
        return {"ipad-product-roadmap"}
    return set()


