def apple_stock_move_metric_signatures(text: str) -> set[str]:
    lower = text.lower()
    signatures = {
        f"percent:{match.group(1)}"
        for match in _compiled_rule(r"(?<!\d)(\d+(?:\.\d+)?)\s*%", 0).finditer(lower)
    }
    signatures |= {
        f"price:{match.group(1)}"
        for match in _compiled_rule(r"\$(\d+(?:\.\d+)?)", 0).finditer(lower)
    }
    signatures |= {
        f"valuation:{match.group(1)}-trillion"
        for match in _compiled_rule(r"(?<!\d)(\d+(?:\.\d+)?)\s*trillion\b", 0).finditer(lower)
    }
    signatures |= {
        f"valuation:{match.group(1)}-trillion"
        for match in _compiled_rule(r"(?<!\d)(\d+(?:\.\d+)?)\s*万亿(?:美元)?", 0).finditer(lower)
    }
    if score_terms(lower, ["nvidia", "英伟达"]) > 0 and score_terms(
        lower,
        [
            "overtake",
            "overtakes",
            "surpassed",
            "reclaim",
            "reclaimed",
            "most valuable company",
            "world's most valuable",
            "world’s most valuable",
            "超越英伟达",
            "重回全球",
            "重返全球",
            "夺回全球",
            "市值冠军",
            "市值第一",
        ],
    ) > 0:
        signatures.add("ranking:apple-over-nvidia")
    return signatures


def service_content_title_tokens_from_text(text: str) -> set[str]:
    return {
        token
        for token in article_tokens(text, "")
        if token not in GENERIC_SERVICE_CONTENT_MERGE_TOKENS
        and not _compiled_rule(r"\d{1,4}", 0).fullmatch(token)
    }


def weak_event_has_title_level_identity(article: Article, event: Event) -> bool:
    if article.relevance_tier != "weak" or event.relevance_tier != "weak":
        return True
    article_title_facets = effective_topic_facets(
        primary_topic_facets(article.title, article.title)
    )
    event_title_facets: set[str] = set()
    for item in event.articles:
        event_title_facets |= effective_topic_facets(
            primary_topic_facets(item.title, item.title)
        )
    if article_title_facets & event_title_facets & EXACT_SHARED_EVENT_TOPIC_FACETS:
        return True
    article_title_tokens = strong_shared_merge_tokens(article_tokens(article.title, ""))
    for item in event.articles:
        item_title_tokens = strong_shared_merge_tokens(article_tokens(item.title, ""))
        shared = article_title_tokens & item_title_tokens
        if len(shared) >= 2:
            return True
        if shared and (
            {token for token in article_tokens(article.title, "") if _compiled_rule(r"\d+(?:\.\d+)?", 0).fullmatch(token)}
            & {token for token in article_tokens(item.title, "") if _compiled_rule(r"\d+(?:\.\d+)?", 0).fullmatch(token)}
        ):
            return True
    return False


def service_content_facets_for_merge(facets: set[str]) -> set[str]:
    service_facets = effective_topic_facets(facets) & SERVICE_CONTENT_TOPIC_FACETS
    detail_facets = service_facets & SERVICE_CONTENT_DETAIL_TOPIC_FACETS
    return detail_facets or service_facets


